insert into stories (story_key, name, category, subcategory, difficulty, description) values ('creation', 'Creation', 'OLD_TESTAMENT', 'Creation', 1, 'In the beginning, God speaks the universe into existence over six days, then rests on the seventh. It establishes God as Creator and sets the pattern for the Sabbath rest that runs throughout Scripture.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Light is separated from darkness', 'Genesis 1:3-5', 'Genesis', 1, 3, 5, 1 from stories where story_key = 'creation';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Sky, land, and vegetation are formed', 'Genesis 1:6-13', 'Genesis', 1, 6, 13, 2 from stories where story_key = 'creation';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Sun, moon, stars, sea creatures, and land animals are made', 'Genesis 1:14-25', 'Genesis', 1, 14, 25, 3 from stories where story_key = 'creation';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Humanity is created and God rests on the seventh day', 'Genesis 1:26-2:3', 'Genesis', 1, 26, 2, 4 from stories where story_key = 'creation';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('fall_of_man', 'The Fall of Man', 'OLD_TESTAMENT', 'Creation', 1, 'Adam and Eve, given one restriction in a perfect garden, are tempted into the one act God forbade. Their disobedience brings shame, blame, and separation from Eden, setting up humanity''s need for redemption.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'The serpent tempts Eve to eat the forbidden fruit', 'Genesis 3:1-5', 'Genesis', 3, 1, 5, 1 from stories where story_key = 'fall_of_man';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Adam and Eve eat the fruit and realize they are naked', 'Genesis 3:6-7', 'Genesis', 3, 6, 7, 2 from stories where story_key = 'fall_of_man';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'God confronts them and pronounces judgment', 'Genesis 3:8-19', 'Genesis', 3, 8, 19, 3 from stories where story_key = 'fall_of_man';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Adam and Eve are expelled from the garden', 'Genesis 3:22-24', 'Genesis', 3, 22, 24, 4 from stories where story_key = 'fall_of_man';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('cain_and_abel', 'Cain and Abel', 'OLD_TESTAMENT', 'Genesis', 2, 'The first brothers bring offerings to God with very different results, and jealousy curdles into the Bible''s first murder. It''s a sobering early picture of sin''s power and God''s justice tempered with mercy.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Cain and Abel bring offerings to the Lord', 'Genesis 4:3-4', 'Genesis', 4, 3, 4, 1 from stories where story_key = 'cain_and_abel';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'God accepts Abel''s offering but not Cain''s', 'Genesis 4:4-5', 'Genesis', 4, 4, 5, 2 from stories where story_key = 'cain_and_abel';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Cain kills Abel in a field', 'Genesis 4:8', 'Genesis', 4, 8, 8, 3 from stories where story_key = 'cain_and_abel';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'God confronts Cain and marks him for protection', 'Genesis 4:9-15', 'Genesis', 4, 9, 15, 4 from stories where story_key = 'cain_and_abel';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('noah', 'Noah and the Flood', 'OLD_TESTAMENT', 'Genesis', 1, 'As human wickedness fills the earth, God chooses one righteous family to survive a great flood that resets creation. Noah''s obedience, and the rainbow that follows, mark God''s covenant never to destroy the earth by flood again.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'God tells Noah to build an ark', 'Genesis 6:13-14', 'Genesis', 6, 13, 14, 1 from stories where story_key = 'noah';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'The flood covers the earth', 'Genesis 7:17-20', 'Genesis', 7, 17, 20, 2 from stories where story_key = 'noah';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Noah sends a dove and the ark comes to rest', 'Genesis 8:8-12', 'Genesis', 8, 8, 12, 3 from stories where story_key = 'noah';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'God sets a rainbow as a covenant sign', 'Genesis 9:12-13', 'Genesis', 9, 12, 13, 4 from stories where story_key = 'noah';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('tower_of_babel', 'The Tower of Babel', 'OLD_TESTAMENT', 'Genesis', 2, 'United by one language, humanity builds a city and tower to make a name for themselves. God confuses their speech and scatters them, a turning point that explains the world''s many nations and languages.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Humanity settles in Shinar and builds a city', 'Genesis 11:1-2', 'Genesis', 11, 1, 2, 1 from stories where story_key = 'tower_of_babel';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'They begin building a tower to reach the heavens', 'Genesis 11:3-4', 'Genesis', 11, 3, 4, 2 from stories where story_key = 'tower_of_babel';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'God confuses their language', 'Genesis 11:5-7', 'Genesis', 11, 5, 7, 3 from stories where story_key = 'tower_of_babel';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'The people are scattered across the earth', 'Genesis 11:8-9', 'Genesis', 11, 8, 9, 4 from stories where story_key = 'tower_of_babel';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('abraham', 'Abraham''s Call', 'OLD_TESTAMENT', 'Patriarchs', 1, 'God calls Abram away from his homeland with a promise: he will become the father of a great nation and a blessing to all peoples. His story becomes the foundation of faith referenced throughout the rest of the Bible.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'God calls Abram to leave his homeland', 'Genesis 12:1-4', 'Genesis', 12, 1, 4, 1 from stories where story_key = 'abraham';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'God promises Abram countless descendants', 'Genesis 15:5', 'Genesis', 15, 5, 5, 2 from stories where story_key = 'abraham';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Abram is renamed Abraham in God''s covenant', 'Genesis 17:5', 'Genesis', 17, 5, 5, 3 from stories where story_key = 'abraham';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Abraham is tested and told to sacrifice Isaac', 'Genesis 22:1-2', 'Genesis', 22, 1, 2, 4 from stories where story_key = 'abraham';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('sarah', 'Sarah', 'OLD_TESTAMENT', 'Patriarchs', 2, 'Barren for decades, Sarah laughs at God''s promise of a son in her old age — then lives to hold him. Her story is about the tension between human doubt and God''s ability to keep an impossible promise.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Sarah, barren, gives Hagar to Abraham', 'Genesis 16:1-3', 'Genesis', 16, 1, 3, 1 from stories where story_key = 'sarah';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Sarah overhears and laughs at God''s promise of a son', 'Genesis 18:10-12', 'Genesis', 18, 10, 12, 2 from stories where story_key = 'sarah';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Sarah gives birth to Isaac in her old age', 'Genesis 21:1-3', 'Genesis', 21, 1, 3, 3 from stories where story_key = 'sarah';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Sarah has Hagar and Ishmael sent away', 'Genesis 21:9-14', 'Genesis', 21, 9, 14, 4 from stories where story_key = 'sarah';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('hagar', 'Hagar', 'OLD_TESTAMENT', 'Patriarchs', 3, 'Mistreated and cast out twice, Hagar is met by God in the wilderness both times. Her story shows God''s care for the overlooked and the outsider, even within a family story centered on someone else''s promise.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Hagar flees from Sarah''s mistreatment', 'Genesis 16:6-8', 'Genesis', 16, 6, 8, 1 from stories where story_key = 'hagar';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'An angel tells Hagar to return and promises Ishmael descendants', 'Genesis 16:9-11', 'Genesis', 16, 9, 11, 2 from stories where story_key = 'hagar';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Hagar and Ishmael are sent into the wilderness', 'Genesis 21:14', 'Genesis', 21, 14, 14, 3 from stories where story_key = 'hagar';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'God provides water and preserves them', 'Genesis 21:17-19', 'Genesis', 21, 17, 19, 4 from stories where story_key = 'hagar';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('lot', 'Lot', 'OLD_TESTAMENT', 'Patriarchs', 2, 'Abraham''s nephew chooses the fertile plain near Sodom, gets pulled into its downfall, and has to be rescued twice — once from war, once from fire. His story is a warning about the cost of choosing by sight alone.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Lot chooses the fertile plain near Sodom', 'Genesis 13:10-11', 'Genesis', 13, 10, 11, 1 from stories where story_key = 'lot';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Lot is captured in a war and rescued by Abraham', 'Genesis 14:11-16', 'Genesis', 14, 11, 16, 2 from stories where story_key = 'lot';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Angels warn Lot to flee before Sodom''s destruction', 'Genesis 19:15-17', 'Genesis', 19, 15, 17, 3 from stories where story_key = 'lot';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Lot escapes as Sodom is destroyed', 'Genesis 19:23-26', 'Genesis', 19, 23, 26, 4 from stories where story_key = 'lot';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('sodom_and_gomorrah', 'Sodom and Gomorrah', 'OLD_TESTAMENT', 'Patriarchs', 2, 'The outcry against two notorious cities reaches God, and two angels arrive to investigate in person. What they find confirms the cities'' judgment, and only Lot''s family escapes the destruction that follows.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'The outcry against Sodom reaches God', 'Genesis 18:20-21', 'Genesis', 18, 20, 21, 1 from stories where story_key = 'sodom_and_gomorrah';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Two angels visit Lot in Sodom', 'Genesis 19:1', 'Genesis', 19, 1, 1, 2 from stories where story_key = 'sodom_and_gomorrah';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'The men of the city surround Lot''s house', 'Genesis 19:4-5', 'Genesis', 19, 4, 5, 3 from stories where story_key = 'sodom_and_gomorrah';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'God destroys Sodom and Gomorrah with fire and sulfur', 'Genesis 19:24-25', 'Genesis', 19, 24, 25, 4 from stories where story_key = 'sodom_and_gomorrah';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('isaac', 'Isaac', 'OLD_TESTAMENT', 'Patriarchs', 2, 'The quiet, steady link between Abraham and Jacob, Isaac''s story centers on the search for a wife within God''s covenant family and the birth of twin sons whose rivalry will shape the next generation.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'A servant is sent to find Isaac a wife', 'Genesis 24:2-4', 'Genesis', 24, 2, 4, 1 from stories where story_key = 'isaac';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Isaac marries Rebekah', 'Genesis 24:63-67', 'Genesis', 24, 63, 67, 2 from stories where story_key = 'isaac';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Rebekah gives birth to twins, Esau and Jacob', 'Genesis 25:24-26', 'Genesis', 25, 24, 26, 3 from stories where story_key = 'isaac';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Isaac blesses Jacob instead of Esau', 'Genesis 27:22-29', 'Genesis', 27, 22, 29, 4 from stories where story_key = 'isaac';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('rebekah', 'Rebekah', 'OLD_TESTAMENT', 'Patriarchs', 3, 'Chosen at a well for her generosity, Rebekah becomes Isaac''s wife and, decades later, the one who engineers her favorite son''s future. Her story is about how far a mother will go for the child she believes is chosen.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Rebekah offers water to Abraham''s servant at the well', 'Genesis 24:15-20', 'Genesis', 24, 15, 20, 1 from stories where story_key = 'rebekah';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Rebekah agrees to leave and marry Isaac', 'Genesis 24:57-58', 'Genesis', 24, 57, 58, 2 from stories where story_key = 'rebekah';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Rebekah gives birth to Esau and Jacob after years of barrenness', 'Genesis 25:21-26', 'Genesis', 25, 21, 26, 3 from stories where story_key = 'rebekah';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Rebekah helps Jacob deceive Isaac for the blessing', 'Genesis 27:5-17', 'Genesis', 27, 5, 17, 4 from stories where story_key = 'rebekah';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('jacob', 'Jacob', 'OLD_TESTAMENT', 'Patriarchs', 2, 'Cunning and ambitious, Jacob schemes his way into his brother''s birthright and blessing, then spends twenty years learning what it''s like to be deceived himself. A nighttime wrestling match with God transforms him into Israel.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Jacob buys Esau''s birthright for a bowl of stew', 'Genesis 25:29-34', 'Genesis', 25, 29, 34, 1 from stories where story_key = 'jacob';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Jacob dreams of a stairway to heaven at Bethel', 'Genesis 28:10-15', 'Genesis', 28, 10, 15, 2 from stories where story_key = 'jacob';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Jacob wrestles with God and is renamed Israel', 'Genesis 32:24-28', 'Genesis', 32, 24, 28, 3 from stories where story_key = 'jacob';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Jacob reconciles with Esau', 'Genesis 33:1-4', 'Genesis', 33, 1, 4, 4 from stories where story_key = 'jacob';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('esau', 'Esau', 'OLD_TESTAMENT', 'Patriarchs', 3, 'A skilled hunter who trades his future for a single meal, Esau spends years vowing revenge on the brother who cheated him. His story ends, unexpectedly, in reconciliation rather than the violence everyone feared.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Esau sells his birthright for a bowl of stew', 'Genesis 25:29-34', 'Genesis', 25, 29, 34, 1 from stories where story_key = 'esau';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Esau discovers Jacob has stolen his father''s blessing', 'Genesis 27:34-36', 'Genesis', 27, 34, 36, 2 from stories where story_key = 'esau';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Esau vows to kill Jacob', 'Genesis 27:41', 'Genesis', 27, 41, 41, 3 from stories where story_key = 'esau';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Esau reconciles with Jacob after years apart', 'Genesis 33:4', 'Genesis', 33, 4, 4, 4 from stories where story_key = 'esau';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('joseph', 'Joseph', 'OLD_TESTAMENT', 'Genesis', 1, 'Sold into slavery by his own jealous brothers, Joseph rises from an Egyptian prison to become second-in-command of the nation through his God-given ability to interpret dreams. His story is one of the Bible''s clearest pictures of forgiveness.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Joseph''s brothers sell him into slavery', 'Genesis 37:23-28', 'Genesis', 37, 23, 28, 1 from stories where story_key = 'joseph';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Joseph is imprisoned after a false accusation', 'Genesis 39:19-20', 'Genesis', 39, 19, 20, 2 from stories where story_key = 'joseph';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Joseph interprets Pharaoh''s dreams and is made ruler', 'Genesis 41:14-41', 'Genesis', 41, 14, 41, 3 from stories where story_key = 'joseph';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Joseph reveals his identity to his brothers', 'Genesis 45:1-4', 'Genesis', 45, 1, 4, 4 from stories where story_key = 'joseph';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('moses', 'Moses'' Early Life', 'OLD_TESTAMENT', 'Moses', 1, 'Rescued as an infant from Pharaoh''s death decree, raised in the Egyptian palace, and later exiled after killing a man, Moses seems an unlikely choice to lead anyone — until God reroutes his life entirely.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Baby Moses is placed in a basket on the Nile', 'Exodus 2:3-4', 'Exodus', 2, 3, 4, 1 from stories where story_key = 'moses';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Moses flees Egypt after killing an Egyptian', 'Exodus 2:11-15', 'Exodus', 2, 11, 15, 2 from stories where story_key = 'moses';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'God speaks to Moses from the burning bush', 'Exodus 3:1-4', 'Exodus', 3, 1, 4, 3 from stories where story_key = 'moses';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Moses returns to Egypt to confront Pharaoh', 'Exodus 5:1', 'Exodus', 5, 1, 1, 4 from stories where story_key = 'moses';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('burning_bush', 'The Burning Bush', 'OLD_TESTAMENT', 'Moses', 2, 'Tending sheep in the wilderness, Moses is stopped by a fire that doesn''t burn out — and a voice that knows his name. It''s the moment his ordinary life ends and his calling as Israel''s deliverer begins.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Moses tends Jethro''s flock near Horeb', 'Exodus 3:1', 'Exodus', 3, 1, 1, 1 from stories where story_key = 'burning_bush';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Moses sees a bush burning but not consumed', 'Exodus 3:2-3', 'Exodus', 3, 2, 3, 2 from stories where story_key = 'burning_bush';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'God calls Moses by name and reveals His identity', 'Exodus 3:4-6', 'Exodus', 3, 4, 6, 3 from stories where story_key = 'burning_bush';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'God commissions Moses to deliver Israel', 'Exodus 3:9-10', 'Exodus', 3, 9, 10, 4 from stories where story_key = 'burning_bush';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('ten_plagues', 'The Ten Plagues', 'OLD_TESTAMENT', 'Exodus', 1, 'God''s confrontation with Pharaoh escalates through ten devastating plagues, each one showing Pharaoh''s gods to be powerless. Pharaoh''s heart hardens again and again, until the final plague finally breaks his resistance.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Moses warns Pharaoh and the plagues begin', 'Exodus 7:14-25', 'Exodus', 7, 14, 25, 1 from stories where story_key = 'ten_plagues';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Pharaoh repeatedly hardens his heart despite the plagues', 'Exodus 8:15', 'Exodus', 8, 15, 15, 2 from stories where story_key = 'ten_plagues';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'The plague of darkness covers Egypt', 'Exodus 10:21-23', 'Exodus', 10, 21, 23, 3 from stories where story_key = 'ten_plagues';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'The final plague strikes Egypt''s firstborn', 'Exodus 12:29-30', 'Exodus', 12, 29, 30, 4 from stories where story_key = 'ten_plagues';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('passover', 'The First Passover', 'OLD_TESTAMENT', 'Exodus', 1, 'On the night of Israel''s final plague, God gives specific instructions for a meal and a mark of blood that will make the difference between death and deliverance. It becomes the defining Jewish festival ever since.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'God institutes the Passover meal and instructions', 'Exodus 12:1-13', 'Exodus', 12, 1, 13, 1 from stories where story_key = 'passover';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Israelites mark their doorposts with lamb''s blood', 'Exodus 12:7', 'Exodus', 12, 7, 7, 2 from stories where story_key = 'passover';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'The death angel passes over the marked homes', 'Exodus 12:12-13', 'Exodus', 12, 12, 13, 3 from stories where story_key = 'passover';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Pharaoh finally releases Israel', 'Exodus 12:31-32', 'Exodus', 12, 31, 32, 4 from stories where story_key = 'passover';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('red_sea', 'Crossing the Red Sea', 'OLD_TESTAMENT', 'Exodus', 1, 'Freed from Egypt but trapped between the sea and Pharaoh''s pursuing army, Israel watches God open an impossible escape route. It becomes the Old Testament''s defining act of deliverance.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Pharaoh pursues the fleeing Israelites', 'Exodus 14:5-9', 'Exodus', 14, 5, 9, 1 from stories where story_key = 'red_sea';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Israel is trapped between Pharaoh''s army and the sea', 'Exodus 14:10-12', 'Exodus', 14, 10, 12, 2 from stories where story_key = 'red_sea';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'God parts the Red Sea for Israel to cross', 'Exodus 14:21-22', 'Exodus', 14, 21, 22, 3 from stories where story_key = 'red_sea';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'The sea closes over the pursuing Egyptian army', 'Exodus 14:26-28', 'Exodus', 14, 26, 28, 4 from stories where story_key = 'red_sea';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('ten_commandments', 'The Ten Commandments', 'OLD_TESTAMENT', 'Exodus', 1, 'At Mount Sinai, God gives Israel more than laws — a covenant identity as His people. The Ten Commandments become the moral backbone referenced throughout the rest of Scripture.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Israel arrives at Mount Sinai', 'Exodus 19:1-2', 'Exodus', 19, 1, 2, 1 from stories where story_key = 'ten_commandments';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'God calls Moses up the mountain', 'Exodus 19:20', 'Exodus', 19, 20, 20, 2 from stories where story_key = 'ten_commandments';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'God gives Moses the Ten Commandments', 'Exodus 20:1-17', 'Exodus', 20, 1, 17, 3 from stories where story_key = 'ten_commandments';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Moses brings the commandments down to the people', 'Exodus 31:18', 'Exodus', 31, 18, 18, 4 from stories where story_key = 'ten_commandments';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('golden_calf', 'The Golden Calf', 'OLD_TESTAMENT', 'Exodus', 2, 'While Moses is still on the mountain receiving God''s law, the people below grow impatient and build an idol to worship instead. It''s a stark picture of how quickly a rescued people can forget their rescuer.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'The people grow impatient waiting for Moses', 'Exodus 32:1', 'Exodus', 32, 1, 1, 1 from stories where story_key = 'golden_calf';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Aaron makes a golden calf for the people to worship', 'Exodus 32:2-4', 'Exodus', 32, 2, 4, 2 from stories where story_key = 'golden_calf';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Moses returns and breaks the stone tablets in anger', 'Exodus 32:19', 'Exodus', 32, 19, 19, 3 from stories where story_key = 'golden_calf';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Moses intercedes for the people before God', 'Exodus 32:11-14', 'Exodus', 32, 11, 14, 4 from stories where story_key = 'golden_calf';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('wilderness', 'The Wilderness Years', 'OLD_TESTAMENT', 'Exodus', 2, 'God provides for Israel''s needs in the wilderness, but fear at the border of the promised land costs an entire generation their chance to enter it. Forty years of wandering follow a single failure of trust.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Israel complains about food and God sends manna', 'Exodus 16:2-15', 'Exodus', 16, 2, 15, 1 from stories where story_key = 'wilderness';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Spies scout the promised land and most bring a fearful report', 'Numbers 13:27-33', 'Numbers', 13, 27, 33, 2 from stories where story_key = 'wilderness';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Israel refuses to enter the land and is condemned to wander', 'Numbers 14:1-34', 'Numbers', 14, 1, 34, 3 from stories where story_key = 'wilderness';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'A new generation nears Canaan forty years later', 'Numbers 14:33-34', 'Numbers', 14, 33, 34, 4 from stories where story_key = 'wilderness';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('joshua', 'Joshua Leads Israel', 'OLD_TESTAMENT', 'Conquest', 2, 'After forty years of wandering, Moses'' successor Joshua leads Israel into the promised land. His story is about a new generation finally taking hold of what God had promised their ancestors.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Joshua succeeds Moses as Israel''s leader', 'Joshua 1:1-2', 'Joshua', 1, 1, 2, 1 from stories where story_key = 'joshua';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Joshua sends spies into Jericho', 'Joshua 2:1', 'Joshua', 2, 1, 1, 2 from stories where story_key = 'joshua';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Israel crosses the Jordan River', 'Joshua 3:14-17', 'Joshua', 3, 14, 17, 3 from stories where story_key = 'joshua';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Joshua leads the conquest of the land', 'Joshua 11:23', 'Joshua', 11, 23, 23, 4 from stories where story_key = 'joshua';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('jericho', 'The Fall of Jericho', 'OLD_TESTAMENT', 'Conquest', 1, 'Israel''s first battle in the promised land is won without a sword — just seven days of marching, a trumpet blast, and a shout. It sets the tone for a conquest defined by faith rather than force.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Joshua sends spies who are hidden by Rahab', 'Joshua 2:1-6', 'Joshua', 2, 1, 6, 1 from stories where story_key = 'jericho';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Israel marches around Jericho''s walls for seven days', 'Joshua 6:3-4', 'Joshua', 6, 3, 4, 2 from stories where story_key = 'jericho';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Priests blow trumpets and the people shout', 'Joshua 6:16-20', 'Joshua', 6, 16, 20, 3 from stories where story_key = 'jericho';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Jericho''s walls collapse', 'Joshua 6:20', 'Joshua', 6, 20, 20, 4 from stories where story_key = 'jericho';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('rahab', 'Rahab', 'OLD_TESTAMENT', 'Conquest', 2, 'A Canaanite woman in a doomed city risks everything to protect two Israelite spies, trading her safety for theirs. Her faith and courage earn her family''s rescue when Jericho falls.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Rahab hides the Israelite spies in Jericho', 'Joshua 2:4-6', 'Joshua', 2, 4, 6, 1 from stories where story_key = 'rahab';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Rahab asks the spies to spare her family', 'Joshua 2:12-13', 'Joshua', 2, 12, 13, 2 from stories where story_key = 'rahab';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Rahab helps the spies escape through a window', 'Joshua 2:15', 'Joshua', 2, 15, 15, 3 from stories where story_key = 'rahab';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Rahab and her family are spared when Jericho falls', 'Joshua 6:22-23', 'Joshua', 6, 22, 23, 4 from stories where story_key = 'rahab';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('gideon', 'Gideon', 'OLD_TESTAMENT', 'Judges', 2, 'A fearful farmer hiding from raiders is called by God to lead Israel''s army — and asks for proof, twice. God then shrinks his army to just 300 men, making the coming victory unmistakably His own.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'An angel calls Gideon to deliver Israel from Midian', 'Judges 6:11-14', 'Judges', 6, 11, 14, 1 from stories where story_key = 'gideon';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Gideon tests God with a fleece of wool', 'Judges 6:36-40', 'Judges', 6, 36, 40, 2 from stories where story_key = 'gideon';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'God reduces Gideon''s army to 300 men', 'Judges 7:2-7', 'Judges', 7, 2, 7, 3 from stories where story_key = 'gideon';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Gideon defeats the Midianites with trumpets and torches', 'Judges 7:19-22', 'Judges', 7, 19, 22, 4 from stories where story_key = 'gideon';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('samson', 'Samson', 'OLD_TESTAMENT', 'Judges', 1, 'Set apart before birth as a deliverer for Israel, Samson is given extraordinary strength — and an extraordinary weakness for the wrong company. His story ends in a final act that costs him his life but defeats his enemies.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'An angel announces Samson''s birth to his parents', 'Judges 13:3-5', 'Judges', 13, 3, 5, 1 from stories where story_key = 'samson';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Samson falls in love with Delilah', 'Judges 16:4', 'Judges', 16, 4, 4, 2 from stories where story_key = 'samson';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Delilah discovers the secret of his strength', 'Judges 16:17-19', 'Judges', 16, 17, 19, 3 from stories where story_key = 'samson';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Samson destroys the Philistine temple in his final act', 'Judges 16:29-30', 'Judges', 16, 29, 30, 4 from stories where story_key = 'samson';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('ruth', 'Ruth', 'OLD_TESTAMENT', 'Judges', 2, 'A story of loyalty set during a famine, Ruth follows a Moabite widow who chooses to stay with her Israelite mother-in-law rather than return to her own people. Her devotion leads her into the family line of David.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Ruth pledges loyalty to Naomi and returns to Bethlehem', 'Ruth 1:16-18', 'Ruth', 1, 16, 18, 1 from stories where story_key = 'ruth';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Ruth gleans grain in the fields of Boaz', 'Ruth 2:2-3', 'Ruth', 2, 2, 3, 2 from stories where story_key = 'ruth';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Boaz agrees to redeem and marry Ruth', 'Ruth 4:9-10', 'Ruth', 4, 9, 10, 3 from stories where story_key = 'ruth';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Ruth and Boaz have a son, Obed', 'Ruth 4:13-17', 'Ruth', 4, 13, 17, 4 from stories where story_key = 'ruth';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('samuel', 'Samuel', 'OLD_TESTAMENT', 'Samuel', 2, 'Dedicated to God''s service before he could remember it, Samuel grows up hearing God''s voice in the night and becomes Israel''s last judge and first great prophet, anointing both of Israel''s first two kings.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Hannah prays for a son and dedicates Samuel to the Lord', '1 Samuel 1:10-11, 27-28', '1 Samuel', 1, 10, 11, 1 from stories where story_key = 'samuel';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Young Samuel hears God''s voice in the night', '1 Samuel 3:4-10', '1 Samuel', 3, 4, 10, 2 from stories where story_key = 'samuel';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Samuel anoints Saul as Israel''s first king', '1 Samuel 10:1', '1 Samuel', 10, 1, 1, 3 from stories where story_key = 'samuel';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Samuel later anoints David as king', '1 Samuel 16:12-13', '1 Samuel', 16, 12, 13, 4 from stories where story_key = 'samuel';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('saul', 'King Saul', 'OLD_TESTAMENT', 'Samuel', 2, 'Israel''s first king starts strong but repeatedly disobeys God''s specific instructions, and his rule unravels from there. Saul''s story is a warning about the cost of partial obedience and jealousy toward a rival''s success.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Saul is anointed as Israel''s first king', '1 Samuel 10:1', '1 Samuel', 10, 1, 1, 1 from stories where story_key = 'saul';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Saul offers an unlawful sacrifice and loses God''s favor', '1 Samuel 13:9-14', '1 Samuel', 13, 9, 14, 2 from stories where story_key = 'saul';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Saul disobeys God''s command regarding the Amalekites', '1 Samuel 15:9-11', '1 Samuel', 15, 9, 11, 3 from stories where story_key = 'saul';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Saul is rejected as king and Samuel anoints David', '1 Samuel 15:26; 16:13', '1 Samuel', 15, 26, 26, 4 from stories where story_key = 'saul';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('david_and_goliath', 'David and Goliath', 'OLD_TESTAMENT', 'David', 1, 'David arrives at the battlefield while Israel''s army is being challenged by a Philistine giant. Refusing Saul''s armor, David confronts Goliath with a sling and five stones, trusting God rather than his own strength.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Goliath challenges the army of Israel', '1 Samuel 17:8-10', '1 Samuel', 17, 8, 10, 1 from stories where story_key = 'david_and_goliath';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'David arrives at the battlefield', '1 Samuel 17:20-23', '1 Samuel', 17, 20, 23, 2 from stories where story_key = 'david_and_goliath';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'David chooses to fight Goliath', '1 Samuel 17:32-37', '1 Samuel', 17, 32, 37, 3 from stories where story_key = 'david_and_goliath';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'David defeats Goliath', '1 Samuel 17:48-51', '1 Samuel', 17, 48, 51, 4 from stories where story_key = 'david_and_goliath';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('jonathan', 'Jonathan', 'OLD_TESTAMENT', 'David', 3, 'The king''s son and the future king become the Bible''s clearest picture of loyal friendship, even as Jonathan''s own father hunts David down. Jonathan repeatedly chooses David''s safety over his own claim to the throne.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Jonathan makes a covenant of friendship with David', '1 Samuel 18:1-3', '1 Samuel', 18, 1, 3, 1 from stories where story_key = 'jonathan';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Jonathan warns David of Saul''s plan to kill him', '1 Samuel 20:35-42', '1 Samuel', 20, 35, 42, 2 from stories where story_key = 'jonathan';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Jonathan helps David escape Saul''s court', '1 Samuel 19:1-2', '1 Samuel', 19, 1, 2, 3 from stories where story_key = 'jonathan';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Jonathan dies alongside Saul in battle', '1 Samuel 31:2', '1 Samuel', 31, 2, 2, 4 from stories where story_key = 'jonathan';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('david_becomes_king', 'David Becomes King', 'OLD_TESTAMENT', 'David', 2, 'From shepherd boy to giant-slayer to fugitive to king, David''s rise is one of the Bible''s great underdog stories, spanning years on the run before he ever wears a crown.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'David is anointed by Samuel as a young shepherd', '1 Samuel 16:12-13', '1 Samuel', 16, 12, 13, 1 from stories where story_key = 'david_becomes_king';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'David flees from Saul for years as a fugitive', '1 Samuel 19:9-10', '1 Samuel', 19, 9, 10, 2 from stories where story_key = 'david_becomes_king';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Saul dies in battle against the Philistines', '1 Samuel 31:4-6', '1 Samuel', 31, 4, 6, 3 from stories where story_key = 'david_becomes_king';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'David is crowned king over all Israel', '2 Samuel 5:3-4', '2 Samuel', 5, 3, 4, 4 from stories where story_key = 'david_becomes_king';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('david_and_bathsheba', 'David and Bathsheba', 'OLD_TESTAMENT', 'David', 2, 'At the height of his power, David abuses it — taking another man''s wife and arranging that man''s death to cover it up. A prophet''s confrontation finally breaks through David''s denial.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'David sees Bathsheba and sends for her', '2 Samuel 11:2-4', '2 Samuel', 11, 2, 4, 1 from stories where story_key = 'david_and_bathsheba';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'David arranges for her husband Uriah''s death in battle', '2 Samuel 11:14-17', '2 Samuel', 11, 14, 17, 2 from stories where story_key = 'david_and_bathsheba';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'The prophet Nathan confronts David with a parable', '2 Samuel 12:1-7', '2 Samuel', 12, 1, 7, 3 from stories where story_key = 'david_and_bathsheba';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'David repents and Bathsheba later bears Solomon', '2 Samuel 12:13, 24', '2 Samuel', 12, 13, 13, 4 from stories where story_key = 'david_and_bathsheba';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('solomon', 'Solomon', 'OLD_TESTAMENT', 'Solomon', 1, 'David''s son inherits a united, peaceful kingdom and famously asks God for wisdom rather than wealth or power. His building of the Jerusalem Temple marks the high point of Israel''s united monarchy.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Solomon becomes king after David', '1 Kings 1:38-39', '1 Kings', 1, 38, 39, 1 from stories where story_key = 'solomon';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Solomon asks God for wisdom', '1 Kings 3:5-9', '1 Kings', 3, 5, 9, 2 from stories where story_key = 'solomon';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Solomon builds the Temple in Jerusalem', '1 Kings 6:1', '1 Kings', 6, 1, 1, 3 from stories where story_key = 'solomon';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'The Queen of Sheba visits Solomon', '1 Kings 10:1-2', '1 Kings', 10, 1, 2, 4 from stories where story_key = 'solomon';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('the_temple', 'Building the Temple', 'OLD_TESTAMENT', 'Solomon', 2, 'Solomon spends seven years constructing the Temple his father David had longed to build. When it''s finished, God''s glory fills the building so powerfully the priests can''t even continue their service.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Solomon begins construction of the Temple', '1 Kings 6:1', '1 Kings', 6, 1, 1, 1 from stories where story_key = 'the_temple';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'The Temple is built to God''s specifications', '1 Kings 6:14-22', '1 Kings', 6, 14, 22, 2 from stories where story_key = 'the_temple';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'The ark of the covenant is brought into the Temple', '1 Kings 8:1-6', '1 Kings', 8, 1, 6, 3 from stories where story_key = 'the_temple';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'God''s glory fills the completed Temple', '1 Kings 8:10-11', '1 Kings', 8, 10, 11, 4 from stories where story_key = 'the_temple';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('elijah', 'Elijah', 'OLD_TESTAMENT', 'Elijah', 1, 'A fierce prophet who confronts kings and false gods head-on, Elijah''s public showdown on Mount Carmel is one of the Old Testament''s most dramatic scenes. Yet his story also shows him at his lowest, before God meets him there.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Elijah announces a drought to King Ahab', '1 Kings 17:1', '1 Kings', 17, 1, 1, 1 from stories where story_key = 'elijah';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Elijah is fed by ravens at the brook Cherith', '1 Kings 17:4-6', '1 Kings', 17, 4, 6, 2 from stories where story_key = 'elijah';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Elijah defeats the prophets of Baal on Mount Carmel', '1 Kings 18:38-40', '1 Kings', 18, 38, 40, 3 from stories where story_key = 'elijah';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Elijah is taken up to heaven in a whirlwind', '2 Kings 2:11', '2 Kings', 2, 11, 11, 4 from stories where story_key = 'elijah';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('mount_carmel', 'The Contest on Mount Carmel', 'OLD_TESTAMENT', 'Elijah', 2, 'One prophet challenges 450 to see whose God will answer by fire. After the prophets of Baal beg and cut themselves for hours in vain, Elijah''s simple prayer is answered instantly and dramatically.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Elijah challenges the prophets of Baal to a contest', '1 Kings 18:22-24', '1 Kings', 18, 22, 24, 1 from stories where story_key = 'mount_carmel';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'The prophets of Baal fail to call down fire', '1 Kings 18:26-29', '1 Kings', 18, 26, 29, 2 from stories where story_key = 'mount_carmel';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Elijah''s sacrifice is consumed by fire from heaven', '1 Kings 18:36-38', '1 Kings', 18, 36, 38, 3 from stories where story_key = 'mount_carmel';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Elijah has the false prophets put to death', '1 Kings 18:40', '1 Kings', 18, 40, 40, 4 from stories where story_key = 'mount_carmel';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('elisha', 'Elisha', 'OLD_TESTAMENT', 'Elijah', 2, 'Elijah''s successor asks for a double portion of his mentor''s spirit and spends decades performing miracles across Israel — healing, providing, and even raising the dead, right up until after his own death.');
