insert into stories (story_key, name, category, subcategory, difficulty, description) values ('naaman', 'Naaman', 'OLD_TESTAMENT', 'Elijah', 2, 'A powerful Syrian commander with a humiliating disease is healed only after he swallows his pride and follows a strange, simple instruction from an Israelite prophet.');
