insert into stories (story_key, name, category, subcategory, difficulty, description) values ('jonah', 'Jonah', 'OLD_TESTAMENT', 'Prophets', 1, 'God sends a reluctant prophet to warn a hostile foreign city, and Jonah runs the other way instead. After being swallowed by a great fish and given a second chance, his story becomes less about the fish and more about a prophet who resents God''s mercy.');
