insert into stories (story_key, name, category, subcategory, difficulty, description) values ('daniel', 'Daniel', 'OLD_TESTAMENT', 'Exile', 1, 'Taken captive to Babylon as a young man, Daniel rises to prominence in a foreign court while refusing to compromise his faith — including a night spent unharmed in a den of lions.');
