insert into stories (story_key, name, category, subcategory, difficulty, description) values ('fiery_furnace', 'The Fiery Furnace', 'OLD_TESTAMENT', 'Exile', 1, 'Three young Israelites in exile refuse to bow to a king''s golden idol, even under threat of death. Thrown into a blazing furnace, they walk out untouched — with an unexpected fourth figure seen beside them.');
