insert into stories (story_key, name, category, subcategory, difficulty, description) values ('lions_den', 'Daniel in the Lions'' Den', 'OLD_TESTAMENT', 'Exile', 1, 'Jealous officials trick a foreign king into a law designed to trap Daniel for his faith. Daniel keeps praying anyway, and a night in a den of lions becomes a public demonstration of God''s protection.');
