insert into stories (story_key, name, category, subcategory, difficulty, description) values ('esther', 'Esther', 'OLD_TESTAMENT', 'Exile', 1, 'Set in the Persian empire, Esther''s story follows a young Jewish woman who becomes queen and then risks her life to save her people from a planned genocide. It''s read as a story of providence working behind the scenes.');
