insert into stories (story_key, name, category, subcategory, difficulty, description) values ('mordecai', 'Mordecai', 'OLD_TESTAMENT', 'Exile', 2, 'Esther''s older cousin raises her, refuses to bow to a proud official, and ultimately persuades her to risk everything for their people — before being honored by the very king who nearly let them be destroyed.');
