insert into stories (story_key, name, category, subcategory, difficulty, description) values ('haman', 'Haman', 'OLD_TESTAMENT', 'Exile', 2, 'A powerful official''s wounded pride at one man''s refusal to bow spirals into a genocidal plot against an entire people — a plot that ultimately destroys Haman himself instead.');
