insert into stories (story_key, name, category, subcategory, difficulty, description) values ('job', 'Job', 'OLD_TESTAMENT', 'Wisdom', 2, 'A blameless, prosperous man loses his family, wealth, and health in a single catastrophic stretch, and spends the rest of the book wrestling with his friends'' bad theology and God''s own unanswerable questions.');
