insert into stories (story_key, name, category, subcategory, difficulty, description) values ('hezekiah', 'Hezekiah', 'OLD_TESTAMENT', 'Kings', 3, 'A reforming king who tears down idol worship faces the largest crisis of his reign when the Assyrian empire besieges Jerusalem. His prayer for deliverance — and later for his own life — are answered both times.');
