insert into stories (story_key, name, category, subcategory, difficulty, description) values ('josiah', 'Josiah', 'OLD_TESTAMENT', 'Kings', 3, 'Crowned king as a child, Josiah grows into one of Judah''s most devoted reformers after a rediscovered scroll of God''s law shakes him to his core, launching a nationwide return to God.');
