insert into stories (story_key, name, category, subcategory, difficulty, description) values ('aarons_rod', 'Aaron''s Staff', 'OLD_TESTAMENT', 'Exodus', 3, 'Facing rebellion against his brother''s God-given priesthood, Moses collects a staff from each tribal leader. Overnight, Aaron''s staff alone sprouts, blossoms, and bears almonds — an unmistakable sign settling the dispute.');
