insert into stories (story_key, name, category, subcategory, difficulty, description) values ('birth_of_john', 'Birth of John the Baptist', 'NEW_TESTAMENT', 'Gospels', 2, 'An elderly, childless priest is told by an angel that he''ll have a son who will prepare the way for the Messiah — news so unbelievable that Zechariah is struck speechless until it comes true.');
