insert into stories (story_key, name, category, subcategory, difficulty, description) values ('birth_of_jesus', 'The Birth of Jesus', 'NEW_TESTAMENT', 'Gospels', 1, 'Long-awaited by prophecy, Jesus'' birth arrives in humble circumstances — a young couple, no room at the inn, shepherds as the first witnesses to news meant for everyone, not just Israel.');
