insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Shepherds visit the newborn Jesus', 'Luke 2:15-16', 'Luke', 2, 15, 16, 4 from stories where story_key = 'birth_of_jesus';
insert into stories (story_key, name, category, subcategory, difficulty, description) values ('wise_men', 'The Visit of the Magi', 'NEW_TESTAMENT', 'Gospels', 1, 'Foreign astrologers follow a star across a great distance to worship a child they believe will be a king, presenting Him gifts before slipping away without reporting back to a threatened Herod.');
