insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'The Magi find Jesus and present their gifts', 'Matthew 2:9-11', 'Matthew', 2, 9, 11, 3 from stories where story_key = 'wise_men';
