insert into stories (story_key, name, category, subcategory, difficulty, description) values ('escape_to_egypt', 'The Escape to Egypt', 'NEW_TESTAMENT', 'Gospels', 2, 'A jealous, threatened king orders the deaths of Bethlehem''s infant boys, but a dream warning gets Jesus'' family safely out of the country in time, fleeing to Egypt until it''s safe to return.');
