insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Herod orders the massacre of infants in Bethlehem', 'Matthew 2:16', 'Matthew', 2, 16, 16, 3 from stories where story_key = 'escape_to_egypt';
