insert into stories (story_key, name, category, subcategory, difficulty, description) values ('jesus_in_the_temple', 'Jesus in the Temple', 'NEW_TESTAMENT', 'Gospels', 2, 'The only recorded story from Jesus'' childhood: a Passover trip to Jerusalem where His parents lose track of him for three anxious days, only to find him deep in conversation with the temple teachers.');
