insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Jesus stays behind in the temple without his parents'' knowledge', 'Luke 2:43', 'Luke', 2, 43, 43, 2 from stories where story_key = 'jesus_in_the_temple';
