insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Jesus comes to John to be baptized', 'Matthew 3:13-15', 'Matthew', 3, 13, 15, 2 from stories where story_key = 'baptism_of_jesus';
