insert into stories (story_key, name, category, subcategory, difficulty, description) values ('nicodemus', 'Nicodemus', 'NEW_TESTAMENT', 'Ministry of Jesus', 2, 'A respected Pharisee comes to Jesus under cover of night with genuine questions, and receives one of the Bible''s most famous answers about what it means to be born again.');
