insert into stories (story_key, name, category, subcategory, difficulty, description) values ('jesus_before_pilate', 'Jesus Before Pilate', 'NEW_TESTAMENT', 'Passion Week', 2, 'Handed over to the Roman governor, Jesus faces a trial where Pilate finds no real charge against him, yet caves to a crowd demanding his death instead of a convicted criminal''s.');
