insert into stories (story_key, name, category, subcategory, difficulty, description) values ('crucifixion', 'The Crucifixion', 'NEW_TESTAMENT', 'Passion Week', 1, 'Jesus carries His own cross to a hill outside Jerusalem, is crucified between two criminals, and dies as darkness covers the land and the temple curtain tears from top to bottom.');
