insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Darkness covers the land as Jesus dies', 'Matthew 27:45-46, 50', 'Matthew', 27, 45, 46, 3 from stories where story_key = 'crucifixion';
