insert into stories (story_key, name, category, subcategory, difficulty, description) values ('burial_of_jesus', 'The Burial of Jesus', 'NEW_TESTAMENT', 'Passion Week', 2, 'A previously unmentioned follower named Joseph steps forward to give Jesus a proper burial, laying His body in his own new tomb and sealing it with a large stone.');
