insert into stories (story_key, name, category, subcategory, difficulty, description) values ('resurrection', 'The Resurrection', 'NEW_TESTAMENT', 'Passion Week', 1, 'Early on the third day, women arrive at Jesus'' tomb expecting to finish preparing His body — and instead find the stone rolled away, the tomb empty, and an angel announcing He has risen.');
