insert into stories (story_key, name, category, subcategory, difficulty, description) values ('road_to_emmaus', 'The Road to Emmaus', 'NEW_TESTAMENT', 'Passion Week', 2, 'Two disillusioned disciples walking to a nearby village are joined by a stranger who explains the Scriptures about the Messiah — and turns out, at the dinner table, to be Jesus himself.');
