insert into stories (story_key, name, category, subcategory, difficulty, description) values ('doubting_thomas', 'Doubting Thomas', 'NEW_TESTAMENT', 'Passion Week', 2, 'Absent when the risen Jesus first appears to the disciples, Thomas refuses to believe without physical proof — proof Jesus offers him personally a week later.');
