insert into stories (story_key, name, category, subcategory, difficulty, description) values ('great_commission', 'The Great Commission', 'NEW_TESTAMENT', 'Passion Week', 2, 'On a mountain in Galilee, the risen Jesus gives His disciples their final marching orders: make disciples of every nation, with the promise of His presence to the very end of the age.');
