insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Jesus declares all authority has been given to him', 'Matthew 28:18', 'Matthew', 28, 18, 18, 3 from stories where story_key = 'great_commission';
