insert into stories (story_key, name, category, subcategory, difficulty, description) values ('ascension', 'The Ascension', 'NEW_TESTAMENT', 'Early Church', 2, 'After forty days of appearances following His resurrection, Jesus gives His disciples final instructions and is taken up into the sky before their eyes, with a promise that He will return the same way.');
