insert into stories (story_key, name, category, subcategory, difficulty, description) values ('pentecost', 'Pentecost', 'NEW_TESTAMENT', 'Early Church', 1, 'Fifty days after the resurrection, the disciples gathered in Jerusalem experience a rushing wind, tongues of fire, and the sudden ability to speak in other languages — the birth of the church.');
