insert into stories (story_key, name, category, subcategory, difficulty, description) values ('stephen', 'Stephen', 'NEW_TESTAMENT', 'Early Church', 2, 'The church''s first deacon becomes its first martyr, boldly recounting Israel''s history before a hostile council and dying in a hail of stones while praying for his killers'' forgiveness.');
