insert into stories (story_key, name, category, subcategory, difficulty, description) values ('ethiopian_eunuch', 'The Ethiopian Eunuch', 'NEW_TESTAMENT', 'Early Church', 3, 'An angel sends Philip to a lonely desert road, where he finds a foreign official puzzling over a passage from Isaiah — and walks him straight to faith and baptism in a matter of minutes.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'An angel sends Philip to a desert road', 'Acts 8:26', 'Acts', 8, 26, 26, 1 from stories where story_key = 'ethiopian_eunuch';
