insert into stories (story_key, name, category, subcategory, difficulty, description) values ('pauls_conversion', 'Paul''s Conversion', 'NEW_TESTAMENT', 'Paul', 1, 'Saul, a zealous persecutor of the early church, is traveling to Damascus to arrest Christians when a blinding light from heaven stops him in his tracks and Jesus speaks to him directly.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Saul travels to Damascus to arrest Christians', 'Acts 9:1-2', 'Acts', 9, 1, 2, 1 from stories where story_key = 'pauls_conversion';
