insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'They face both success and persecution in city after city', 'Acts 14:1-6, 19', 'Acts', 14, 1, 6, 3 from stories where story_key = 'pauls_missionary_journeys';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'They return to report all God had done through them', 'Acts 14:26-27', 'Acts', 14, 26, 27, 4 from stories where story_key = 'pauls_missionary_journeys';
