insert into stories (story_key, name, category, subcategory, difficulty, description) values ('paul_and_silas', 'Paul and Silas in Prison', 'NEW_TESTAMENT', 'Paul', 2, 'Beaten and jailed in Philippi for casting out a spirit, Paul and Silas spend midnight singing hymns instead of despairing — right before an earthquake shakes the prison doors open.');
