insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'An earthquake shakes open the prison doors', 'Acts 16:26', 'Acts', 16, 26, 26, 3 from stories where story_key = 'paul_and_silas';
