insert into stories (story_key, name, category, subcategory, difficulty, description) values ('paul_in_athens', 'Paul in Athens', 'NEW_TESTAMENT', 'Paul', 3, 'Waiting in a city full of idols, Paul can''t stay silent — he reasons daily in the marketplace and eventually addresses Athens'' philosophers directly about the ''unknown god'' they already worship.');
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Paul waits in Athens, distressed by its idols', 'Acts 17:16', 'Acts', 17, 16, 16, 1 from stories where story_key = 'paul_in_athens';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Paul reasons in the synagogue and marketplace daily', 'Acts 17:17', 'Acts', 17, 17, 17, 2 from stories where story_key = 'paul_in_athens';
