insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Paul sails for Rome as a prisoner', 'Acts 27:1', 'Acts', 27, 1, 1, 1 from stories where story_key = 'pauls_shipwreck';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'A violent storm drives the ship for many days', 'Acts 27:18-20', 'Acts', 27, 18, 20, 2 from stories where story_key = 'pauls_shipwreck';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'The ship runs aground and breaks apart', 'Acts 27:41', 'Acts', 27, 41, 41, 3 from stories where story_key = 'pauls_shipwreck';
insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Everyone aboard reaches shore safely as Paul foretold', 'Acts 27:44', 'Acts', 27, 44, 44, 4 from stories where story_key = 'pauls_shipwreck';
