insert into events (story_id, event_text, scripture_reference, book, chapter, verse_start, verse_end, sequence) select id, 'Paul arrives in Rome still a prisoner', 'Acts 28:16', 'Acts', 28, 16, 16, 1 from stories where story_key = 'paul_in_rome';
